local a=peripheral.find("modem")local b=require("index")local c=require("logs.Log").new("logistic")local d=b.create()local function e(f,g)if g==nil then g="%s"end;local h={}for i in string.gmatch(f,"([^"..g.."]+)")do table.insert(h,i)end;return h end;local j={map=function(k)if k[2]=="sender"then b.addSender(d,k[3])end;if k[2]=="receiver"then b.addReceiver(d,k[3],k[4])end end,list=function(k)print("Senders:")print(b.listSenders(d))print("Receivers:")print(b.listReceivers(d))end,search=function(k)local l=k[3]if k[2]=="sender"then local m=b.searchSenders(d,l)if#m==0 then print("No senders found with name: "..l)else local n=false;for o,p in ipairs(m)do if p==l then n=true;print("Sender found: "..p)end end;if not n then print("No senders found with name: "..l)end end elseif k[2]=="receiver"then local q=b.getReceiver(d,k[3])if q==nil then print("Receiver not found: "..k[3])else print("Receiver found: "..k[3])end else print("Unknown search type: "..k[2])end end,exit=function(k)print("Exiting...")return false end,help=function(k)print("Available commands:")print("map sender <name> - Add a sender to the index")print("map receiver <name> <address> - Add a receiver to the index")print("list - List all senders and receivers")print("search sender <name> - Search for a sender by name")print("search receiver <address> - Search for a receiver by address")print("exit - Exit the program")end}local function r(s)local t=a.callRemote(s,"size")for u=1,t do local v=a.callRemote(s,"getItemDetail",u)if v==nil then return true end end;return false end;local function w()while true do local k=e(read()," ")if j[k[1]]==nil then print("Unknown command: "..k[1])c.warn("Unknown command: "..k[1])else local x=j[k[1]](k)if x==false then break end end end end;local function y(z,A,u)local q=b.getReceiver(d,z)if q==nil then c.error("Receiver "..z.." not found in index.")return end;if r(q)then a.callRemote(A,"pushItems",q,u)c.debug("Transferred from "..A.." to "..z)print("Transferred from "..A.." to "..z)else c.warn("No empty slots available in receiver "..z)print("No empty slots available in receiver "..z)end end;local function B(p)for u,v in pairs(a.callRemote(p,"list"))do if v==nil then goto C end;local D=a.callRemote(p,"getItemDetail",u)local E=D.package;if E==nil then y("Main",p,u)else local z=E.getAddress()if z~=nil then y(z,p,u)else c.warn("No address found for item in slot "..u.." of sender "..p)print("No address found for item in slot "..u.." of sender "..p)end end::C::end end;local function F()while true do local m=b.getAllSenders(d)if#m==0 then c.warn("No senders found in index.")print("No senders found in index.")sleep(5)break end;for G,p in ipairs(m)do B(p)end end end;if#arg>0 then if arg[1]=="mapping"then print("Mapping")w()end end;print("Transferring")F()
